package com.reau.app.aa

import org.junit.Assert.assertEquals
import org.junit.Assert.assertTrue
import org.junit.Test

/**
 * The app carries the protobuf 4.x runtime (plan 20, item 3): the 3.x line is out of support on 31/03/2027, and the messages of Android Auto,
 * generated by protoc 3.25.1, are read by the 4.x one.
 */
class ProtobufRuntimeTest {
    /** `RuntimeVersion` came with the 4.x runtime (its gencode check); the 3.x one has no such class. */
    private val runtimeIs4x = runCatching { Class.forName("com.google.protobuf.RuntimeVersion") }.isSuccess

    @Test
    fun theAppCarriesTheFourRuntime() {
        assertTrue("the 4.x runtime must be on the classpath", runtimeIs4x)
    }

    /** The classes REau has were generated by protoc 3.25.1; the 4.x runtime reads them (the message round trip). */
    @Test
    fun aMessageGeneratedByTheOldProtocRoundTripsOnTheAppsRuntime() {
        val message = com.reau.app.aa.proto.Common.HeadUnitInfo.newBuilder().setMake("REau").setModel("test").setHeadUnitMake("m").setHeadUnitModel("h").build()
        val bytes = message.toByteArray()
        assertEquals(message, com.reau.app.aa.proto.Common.HeadUnitInfo.parseFrom(bytes))
        assertTrue(com.reau.app.aa.proto.Common.getDescriptor().messageTypes.isNotEmpty())
    }
}
